mapper.select:
SELECT 
  FROM user_channel_binding ucb
 WHERE ucb.user_id = #{userId}
   AND ucb.channel_type = #{channelType}
   AND ucb.status = 'ACTIVE'
 ORDER BY ucb.created_at DESC

mapper.update:
UPDATE user_channel_binding
   SET status = 'REVOKED',
       updated_at = #{now}
 WHERE user_id = #{userId}
   AND channel_type = #{channelType}
AND workspace_id IS NULL
AND workspace_id = #{workspaceId}
